      val b = arrayOf(1, 2, 3)
      println(a == b) // references comparison
  }' After the quick-fix is applied: 'fun test() {
      val a = arrayOf(1, 2, 3)
      val b = arrayOf(1, 2, 3)
      println(a.contentEquals(b))
  }' Inspection ID: ReplaceArrayEqualityOpWithArraysEquals

